namespace Aict.DesktopPortal {
    sealed class Session {
        internal string Id,Root;internal bool Running;
        public override string ToString(){return (Running?"正在运行":"已停止 · 保留记录")+" · "+Directory.GetCreationTime(Root).ToString("MM-dd HH:mm");}
    }
    sealed class BrowserRun {
        public string Id,Sid,Browser,ValueName,Domain,CreatedUtc,TaskName,Phase,Error,CleanupExe;
        public bool RegistryWritten,RegistryRestored,TaskRemoved;
    }
    static class Program {
        internal static readonly JavaScriptSerializer Json=new JavaScriptSerializer {MaxJsonLength=4194304};
        internal static readonly UTF8Encoding Utf8=new UTF8Encoding(false,true);
        internal static IEnumerable<object> Items(object value){return ((global::System.Collections.IEnumerable)value).Cast<object>();}
        internal static string Sid {get{return WindowsIdentity.GetCurrent().User.Value;}}
        internal static string UserRoot {get{return Path.Combine(Environment.GetFolderPath(Environment.SpecialFolder.LocalApplicationData),"AICT","DesktopEntry-v1");}}
        internal static string Exe {get{return Assembly.GetExecutingAssembly().Location;}}
        internal static bool Vmware(){using(var k=Registry.LocalMachine.OpenSubKey(@"HARDWARE\DESCRIPTION\System\BIOS"))return k!=null && Convert.ToString(k.GetValue("SystemManufacturer")).Contains("VMware") && Convert.ToString(k.GetValue("SystemProductName")).Contains("VMware");}
        internal static void Guard(){if(!Vmware())throw new InvalidOperationException("VMware guest required; no shortcut, file, task, or policy changes performed.");}
        internal static string Hash(string file){using(var sha=SHA256.Create())using(var stream=File.OpenRead(file))return BitConverter.ToString(sha.ComputeHash(stream)).Replace("-","").ToLowerInvariant();}
        internal static Dictionary<string,object> Read(string file){var f=new FileInfo(file);if(!f.Exists || f.Length>4194304 || (f.Attributes&FileAttributes.ReparsePoint)!=0)throw new IOException("Expected bounded ordinary file");using(var stream=new FileStream(file,FileMode.Open,FileAccess.Read,FileShare.ReadWrite|FileShare.Delete))using(var reader=new StreamReader(stream,Utf8))return Json.Deserialize<Dictionary<string,object>>(reader.ReadToEnd());}
        internal static void Save(string file,object value){Directory.CreateDirectory(Path.GetDirectoryName(file));string temp=file+"."+Guid.NewGuid().ToString("N")+".tmp";using(var s=new FileStream(temp,FileMode.CreateNew,FileAccess.Write,FileShare.None)){byte[] data=Utf8.GetBytes(Json.Serialize(value));s.Write(data,0,data.Length);s.Flush(true);}if(File.Exists(file))File.Replace(temp,file,null);else File.Move(temp,file);}
        internal static List<Session> Sessions(){var result=new List<Session>();string parent=Environment.GetFolderPath(Environment.SpecialFolder.CommonApplicationData);foreach(string root in Directory.GetDirectories(parent,"AICT-Interactive-*",SearchOption.TopDirectoryOnly).Take(256))try{
            if((File.GetAttributes(root)&FileAttributes.ReparsePoint)!=0)continue;string id=Path.GetFileName(root).Substring("AICT-Interactive-".Length);Guid parsed;if(!Guid.TryParseExact(id,"N",out parsed))continue;
            var c=Read(Path.Combine(root,"config.json"));if(Convert.ToString(c["runId"])!=id || Convert.ToString(c["probeSid"])!=Sid)continue;
            bool running=false;try{using(var service=new ServiceController("AICT-Interactive-"+id))running=service.Status==ServiceControllerStatus.Running;}catch(InvalidOperationException){}
            result.Add(new Session {Id=id,Root=root,Running=running});
        }catch(IOException){}catch(UnauthorizedAccessException){}return result.OrderByDescending(s=>s.Running).ThenByDescending(s=>Directory.GetCreationTimeUtc(s.Root)).ToList();}
        internal static void Open(Session session){
            Guard();using(var service=new ServiceController("AICT-Interactive-"+session.Id))if(service.Status!=ServiceControllerStatus.Running)throw new InvalidOperationException("测试后台已停止。保存的规则仍可查看；不会打开空白开发预览。旧测试包会在60分钟后自动结束。");
            var hashes=Read(Path.Combine(Path.GetDirectoryName(Exe),"BASE-APP-HASHES.json"));
            foreach(var pair in hashes){string rel=pair.Key;if(rel.Contains("..") || rel.Contains(":") || Path.IsPathRooted(rel))throw new IOException("Invalid frozen application path");string file=Path.Combine(session.Root,rel.Replace('/',Path.DirectorySeparatorChar));if(Hash(file)!=Convert.ToString(pair.Value))throw new IOException("原界面文件与已验证版本不一致，拒绝启动。请保留现有数据。");}
            Process.Start(new ProcessStartInfo(Path.Combine(session.Root,@"App\Aict.Desktop.exe"),"--vm-service \""+Path.Combine(session.Root,"connection.json")+"\""){UseShellExecute=false});
        }
        internal static string Shortcut(){
            Guard();string version=Hash(Exe).Substring(0,12);string targetRoot=Path.Combine(UserRoot,version);Directory.CreateDirectory(targetRoot);
            foreach(string name in new[]{"专注计划.exe","BASE-APP-HASHES.json"}){string source=Path.Combine(Path.GetDirectoryName(Exe),name),dest=Path.Combine(targetRoot,name);if(!File.Exists(dest))File.Copy(source,dest);else if(Hash(source)!=Hash(dest))throw new IOException("入口副本已变化，未覆盖。");}
            string target=Path.Combine(targetRoot,"专注计划.exe"),desktop=Environment.GetFolderPath(Environment.SpecialFolder.DesktopDirectory),link=Path.Combine(desktop,"专注计划（测试版）.lnk");
            dynamic shell=Activator.CreateInstance(Type.GetTypeFromProgID("WScript.Shell"));try{if(File.Exists(link)){dynamic old=shell.CreateShortcut(link);try{string oldTarget=Convert.ToString(old.TargetPath);if(!oldTarget.StartsWith(UserRoot+Path.DirectorySeparatorChar,StringComparison.OrdinalIgnoreCase))throw new IOException("桌面已有同名快捷方式，未覆盖。");}finally{Marshal.FinalReleaseComObject(old);}}
                dynamic shortcut=shell.CreateShortcut(link);try{shortcut.TargetPath=target;shortcut.WorkingDirectory=targetRoot;shortcut.Description="AICT 正常应用入口；连接已有后台，不打开开发预览";shortcut.IconLocation=target+",0";shortcut.Save();}finally{Marshal.FinalReleaseComObject(shortcut);}
            }finally{Marshal.FinalReleaseComObject(shell);}return target;
        }
        internal static string BrowserExe(string browser){string name=browser=="Edge"?@"Microsoft\Edge\Application\msedge.exe":@"Google\Chrome\Application\chrome.exe";foreach(string dir in new[]{Environment.GetFolderPath(Environment.SpecialFolder.ProgramFilesX86),Environment.GetFolderPath(Environment.SpecialFolder.ProgramFiles),Environment.GetFolderPath(Environment.SpecialFolder.LocalApplicationData)}){string file=Path.Combine(dir,name);if(File.Exists(file))return file;}throw new IOException("未找到这个浏览器，未下载或安装任何软件。");}
        internal static string Journal(string id){Guid parsed;if(!Guid.TryParseExact(id,"N",out parsed))throw new ArgumentException("Invalid browser session ID");return Path.Combine(UserRoot,"browser-"+id+".json");}
        internal static BrowserRun LoadRun(string id){var data=Json.Deserialize<BrowserRun>(File.ReadAllText(Journal(id),Utf8));BrowserPolicySlot.PathFor(data.Browser);int slot;
            if(data.Id!=id || data.Sid!=Sid || data.Domain!=BrowserPolicySlot.TestDomain || !int.TryParse(data.ValueName,out slot) || slot<1 || slot>1000 || data.TaskName!="AICT-BrowserPilot-"+id)throw new IOException("Invalid browser journal; no registry changes performed");return data;}
        internal static void RegisterCleanup(BrowserRun run,string executable){dynamic scheduler=Activator.CreateInstance(Type.GetTypeFromProgID("Schedule.Service"));try{scheduler.Connect();dynamic folder=scheduler.GetFolder("\\");dynamic task=scheduler.NewTask(0);task.RegistrationInfo.Description="AICT browser pilot expiry; current user only; "+run.Id;task.Principal.UserId=Sid;task.Principal.LogonType=3;task.Principal.RunLevel=0;task.Settings.Enabled=true;task.Settings.StartWhenAvailable=true;task.Settings.DisallowStartIfOnBatteries=false;task.Settings.StopIfGoingOnBatteries=false;task.Settings.ExecutionTimeLimit="PT2M";dynamic trigger=task.Triggers.Create(1);trigger.StartBoundary=DateTime.Now.AddMinutes(15).ToString("s");trigger.Enabled=true;dynamic action=task.Actions.Create(0);action.Path=executable;action.Arguments="--browser-cleanup "+run.Id;folder.RegisterTaskDefinition(run.TaskName,task,2,Sid,null,3,null);dynamic actual=folder.GetTask(run.TaskName);if(actual.Definition.Actions.Count!=1 || Convert.ToString(actual.Definition.Actions.Item(1).Path)!=executable || Convert.ToString(actual.Definition.Actions.Item(1).Arguments)!="--browser-cleanup "+run.Id || actual.Definition.Principal.RunLevel!=0 || actual.Definition.Principal.LogonType!=3)throw new IOException("自动恢复任务未通过读回，未写入网站策略。");}finally{Marshal.FinalReleaseComObject(scheduler);}}
        internal static bool RemoveCleanup(BrowserRun run){dynamic scheduler=Activator.CreateInstance(Type.GetTypeFromProgID("Schedule.Service"));try{scheduler.Connect();dynamic folder=scheduler.GetFolder("\\"),task;try{task=folder.GetTask(run.TaskName);}catch(COMException e){if((uint)e.ErrorCode==0x80070002)return true;throw;}string target=Convert.ToString(task.Definition.Actions.Item(1).Path);string args=Convert.ToString(task.Definition.Actions.Item(1).Arguments);
            string principal=Convert.ToString(task.Definition.Principal.UserId);if(!principal.StartsWith("S-1-",StringComparison.Ordinal))principal=((SecurityIdentifier)new NTAccount(principal).Translate(typeof(SecurityIdentifier))).Value;
            if(task.Definition.Actions.Count!=1 || args!="--browser-cleanup "+run.Id || !string.Equals(target,run.CleanupExe,StringComparison.OrdinalIgnoreCase) || !Path.GetFullPath(target).StartsWith(UserRoot+Path.DirectorySeparatorChar,StringComparison.OrdinalIgnoreCase) || principal!=Sid || task.Definition.Principal.RunLevel!=0)throw new IOException("清理任务已变化，未删除。");folder.DeleteTask(run.TaskName,0);return true;}finally{Marshal.FinalReleaseComObject(scheduler);}}
        static FileStream OperationLock(){Directory.CreateDirectory(UserRoot);var wait=Stopwatch.StartNew();while(true){try{return new FileStream(Path.Combine(UserRoot,"browser-operation.lock"),FileMode.OpenOrCreate,FileAccess.ReadWrite,FileShare.None);}catch(IOException){if(wait.Elapsed.TotalSeconds>10)throw;global::System.Threading.Thread.Sleep(100);}}}
        internal static BrowserRun Apply(string browser){Guard();using(var held=OperationLock())return ApplyLocked(browser);}
        static BrowserRun ApplyLocked(string browser){
            Guard();BrowserExe(browser);string path=BrowserPolicySlot.PathFor(browser);foreach(var hive in new[]{Registry.CurrentUser,Registry.LocalMachine})using(var allow=hive.OpenSubKey(path+@"\URLAllowlist")){if(allow!=null && allow.ValueCount>0)throw new InvalidOperationException("发现已有网站允许策略，可能覆盖封锁效果。本次不修改，请导出诊断。");}
            foreach(var hive in new[]{Registry.CurrentUser,Registry.LocalMachine})using(var existing=hive.OpenSubKey(path+@"\URLBlocklist"))if(existing!=null && existing.ValueCount>0)throw new InvalidOperationException("发现已有网站封锁策略。为避免把旧限制当成本次效果，本轮保留原配置、不叠加测试。");
            foreach(string file in Directory.Exists(UserRoot)?Directory.GetFiles(UserRoot,"browser-*.json"):new string[0]){string id=Path.GetFileNameWithoutExtension(file).Substring(8);var previous=LoadRun(id);if(previous.Browser==browser && !previous.RegistryRestored)throw new InvalidOperationException("此浏览器已有未恢复的测试，先点击恢复。关闭窗口不解除测试。");}
            string name;using(var key=Registry.CurrentUser.OpenSubKey(path+@"\URLBlocklist"))name=BrowserPolicySlot.Available(key==null?new string[0]:key.GetValueNames());
            var run=new BrowserRun {Id=Guid.NewGuid().ToString("N"),Sid=Sid,Browser=browser,ValueName=name,Domain=BrowserPolicySlot.TestDomain,CreatedUtc=DateTime.UtcNow.ToString("o"),Phase="Prepared"};run.TaskName="AICT-BrowserPilot-"+run.Id;
            Save(Journal(run.Id),run);string stable=Shortcut();run.CleanupExe=stable;Save(Journal(run.Id),run);RegisterCleanup(run,stable);
            try {using(var key=Registry.CurrentUser.CreateSubKey(path+@"\URLBlocklist")){if(key.GetValueNames().Contains(name,StringComparer.OrdinalIgnoreCase))throw new IOException("预留位置已被其他配置占用，未覆盖。");key.SetValue(name,run.Domain,RegistryValueKind.String);key.Flush();run.RegistryWritten=key.GetValueKind(name)==RegistryValueKind.String && Convert.ToString(key.GetValue(name))==run.Domain;}
                if(!run.RegistryWritten)throw new IOException("网站策略读回不一致。");run.Phase="RegistryPublishedBrowserUnverified";Save(Journal(run.Id),run);return run;
            }catch(Exception e){run.Error=e.Message;Save(Journal(run.Id),run);throw;}
        }
        internal static BrowserRun Restore(string id){Guard();using(var held=OperationLock())return RestoreLocked(id);}
        static BrowserRun RestoreLocked(string id){Guard();var run=LoadRun(id);try{using(var key=Registry.CurrentUser.OpenSubKey(BrowserPolicySlot.PathFor(run.Browser)+@"\URLBlocklist",true)){if(key!=null && key.GetValueNames().Contains(run.ValueName,StringComparer.OrdinalIgnoreCase)){if(!BrowserPolicySlot.OwnValue(run.Domain,Convert.ToString(key.GetValue(run.ValueName)),key.GetValueKind(run.ValueName)==RegistryValueKind.String))throw new IOException("测试位置内容已被其他工具改变，未删除。请保留诊断。");key.DeleteValue(run.ValueName,false);key.Flush();}run.RegistryRestored=key==null || !key.GetValueNames().Contains(run.ValueName,StringComparer.OrdinalIgnoreCase);}
                run.TaskRemoved=RemoveCleanup(run);run.Phase="OwnValueRemovedBrowserRefreshPending";run.Error=null;Save(Journal(id),run);return run;
            }catch(Exception e){run.Error=e.Message;Save(Journal(id),run);throw;}}
        [STAThread] static int Main(string[] args){Application.EnableVisualStyles();Application.SetCompatibleTextRenderingDefault(false);try{
            if(args.Length==2 && args[0]=="--self-test"){Directory.CreateDirectory(args[1]);using(var form=new PortalForm(true)){form.Show();Application.DoEvents();using(var bitmap=new Bitmap(form.Width,form.Height)){form.DrawToBitmap(bitmap,new Rectangle(0,0,form.Width,form.Height));bitmap.Save(Path.Combine(args[1],"entry.png"));}form.ShowBrowser();Application.DoEvents();form.ValidateBrowserSelection();using(var bitmap=new Bitmap(form.Width,form.Height)){form.DrawToBitmap(bitmap,new Rectangle(0,0,form.Width,form.Height));bitmap.Save(Path.Combine(args[1],"browser.png"));}}return 0;}
            Guard();if(args.Length==2 && args[0]=="--browser-cleanup"){Restore(args[1]);return 0;}if(args.Length!=0)throw new ArgumentException("Unknown entry arguments");Application.Run(new PortalForm(false));return 0;
        }catch(Exception e){if(args.Length>0)Console.Error.WriteLine(e);else MessageBox.Show(e.Message,"专注计划",MessageBoxButtons.OK,MessageBoxIcon.Information);return 1;}}
    }
    sealed class PortalForm:Form {
        readonly bool renderOnly;readonly ComboBox sessions=new ComboBox(),browser=new ComboBox();readonly TextBox summary=new TextBox(),message=new TextBox();readonly Panel content=new Panel();readonly Label state=new Label();readonly ComboBox observed=new ComboBox();readonly List<Session> available;
        internal PortalForm(bool renderOnly){this.renderOnly=renderOnly;Text="专注计划 · 测试版";Font=new Font("Microsoft YaHei UI",10);ClientSize=new Size(900,690);MinimumSize=new Size(900,720);StartPosition=FormStartPosition.CenterScreen;BackColor=Color.FromArgb(244,247,251);
            var heading=new Label {Text="专注计划",Font=new Font(Font.FontFamily,23,FontStyle.Bold),ForeColor=Color.White,BackColor=Color.FromArgb(21,47,69),Dock=DockStyle.Top,Height=86,Padding=new Padding(24,20,0,0)};Controls.Add(heading);
            var nav=new FlowLayoutPanel {Location=new Point(22,100),Size=new Size(856,48)};Controls.Add(nav);Button(nav,"我的应用规则",()=>ShowApps(),180);Button(nav,"下一步：网站测试",()=>ShowBrowser(),180);Button(nav,"创建桌面快捷方式",()=>{Program.Shortcut();Note("桌面已创建“专注计划（测试版）”。以后双击它即可，不用进入 App 文件夹。 ");},190);Button(nav,"导出诊断",Export,140);
            content.Location=new Point(24,158);content.Size=new Size(850,460);content.Anchor=AnchorStyles.Top|AnchorStyles.Bottom|AnchorStyles.Left|AnchorStyles.Right;Controls.Add(content);
            message.Location=new Point(24,625);message.Size=new Size(850,45);message.Multiline=true;message.ReadOnly=true;message.BorderStyle=BorderStyle.None;message.BackColor=BackColor;message.Anchor=AnchorStyles.Bottom|AnchorStyles.Left|AnchorStyles.Right;Controls.Add(message);
