        }
        void Note(string text){message.Text=text;}
        internal void ValidateBrowserSelection(){if(Convert.ToString(browser.SelectedItem)!="Edge" || Convert.ToString(observed.SelectedItem)!="尚未人工确认")throw new InvalidOperationException("Browser selectors were not initialized");}
        void Safe(Action action){if(renderOnly)return;try{action();}catch(Exception e){Note(e.Message);MessageBox.Show(this,e.Message,"操作未完成",MessageBoxButtons.OK,MessageBoxIcon.Information);}}
        void Button(Control parent,string text,Action action,int width){var b=new Button {Text=text,Width=width,Height=38,FlatStyle=FlatStyle.Flat,Margin=new Padding(0,0,10,6),BackColor=Color.White};b.FlatAppearance.BorderColor=Color.FromArgb(204,214,225);b.Click+=(s,e)=>Safe(action);parent.Controls.Add(b);}
        void TextAt(string text,int y,int height=38){content.Controls.Add(new Label {Text=text,Location=new Point(0,y),Size=new Size(830,height),ForeColor=Color.FromArgb(29,45,64)});}
        internal void ShowApps(){content.Controls.Clear();TextAt("打开原有规则，关闭界面不会直接解除封锁",0);sessions.Items.Clear();foreach(var entry in available)sessions.Items.Add(entry);sessions.DropDownStyle=ComboBoxStyle.DropDownList;sessions.Location=new Point(0,44);sessions.Width=530;content.Controls.Add(sessions);sessions.SelectedIndexChanged+=(s,e)=>ShowSaved();if(sessions.Items.Count>0)sessions.SelectedIndex=0;
            var row=new FlowLayoutPanel {Location=new Point(0,90),Size=new Size(830,48)};content.Controls.Add(row);Button(row,"打开我的规则",()=>{var selected=sessions.SelectedItem as Session;if(selected==null)throw new InvalidOperationException("没有找到原测试会话。请保留旧文件夹；不会创建空白开发版。");Program.Open(selected);},220);
            summary.Location=new Point(0,148);summary.Size=new Size(830,245);summary.Multiline=true;summary.ReadOnly=true;summary.ScrollBars=ScrollBars.Vertical;summary.BackColor=Color.White;content.Controls.Add(summary);
            TextAt("应用按内容识别：同一程序的改名、复制版本也会受限。\r\n旧应用实验在60分钟后自动结束；后台停止后，下方仍展示最后保存的规则记录。",401,56);ShowSaved();}
        void ShowSaved(){try{var selected=sessions.SelectedItem as Session;if(selected==null){summary.Text=renderOnly?"我的应用限制\r\n启用 · 封锁 2 分钟 / 休息 1 分钟\r\n限制：Target.exe（其同内容副本 Renamed.exe 也受限）":"没有找到当前用户的旧测试记录。此入口不会新建规则库、安装服务或打开开发预览。";return;}var response=Program.Read(Path.Combine(selected.Root,@"state\workspace-status.json"));Dictionary<string,object> status=(Dictionary<string,object>)response["status"],policy=(Dictionary<string,object>)status["policy"];var apps=new Dictionary<string,string>();foreach(Dictionary<string,object> a in Program.Items(status["applications"]))apps[Convert.ToString(a["id"])]=Convert.ToString(a["fileName"]);
            var lines=new List<string>{selected.Running?"原后台正在运行；点击“打开我的规则”查看实时状态。":"原测试后台已停止。以下是保留的历史记录，不代表当前封锁状态。","记录时间："+DateTimeOffset.Parse(Convert.ToString(status["effectiveUtc"])).ToLocalTime().ToString("MM-dd HH:mm:ss"),"修改等待："+policy["changeDelay"],""};foreach(Dictionary<string,object> g in Program.Items(policy["groups"])){lines.Add(Convert.ToString(g["name"])+(Convert.ToBoolean(g["enabled"])?" · 启用":" · 停用"));lines.Add("应用："+string.Join("、",Program.Items(g["applicationIds"]).Select(id=>apps.ContainsKey(Convert.ToString(id))?apps[Convert.ToString(id)]:"已登记应用")));if(g["cycle"]!=null){var c=(Dictionary<string,object>)g["cycle"];lines.Add("循环：封锁 "+c["blockFor"]+" / 休息 "+c["restFor"]);}lines.Add("");}summary.Text=string.Join(Environment.NewLine,lines);
            }catch(Exception e){summary.Text="保留记录暂时无法读取；未创建或重置任何规则。\r\n"+e.Message;}}
        internal void ShowBrowser(){content.Controls.Clear();TextAt("网站封锁机制测试 · 只针对 example.com",0);TextAt("这是下一阶段的机制试验，尚未接入应用规则的时段与锁定。\r\n规则由浏览器原生策略执行，不依赖插件；本页恢复按钮只供实验收尾。",35,60);
