            TextAt("在策略页点击“重新加载策略”，确认 URLBlocklist 状态正常，然后新开测试网站。\r\n仅网络错误、打不开网页都不能证明封锁成功；应看到浏览器明确的管理员封锁提示。\r\nEdge 的个人微软账号配置文件可能不适用；请如实记录策略状态，不修改原账号。",250,90);
            observed.Items.Clear();observed.Items.AddRange(new object[]{"尚未人工确认","看到管理员封锁提示","策略不适用 / 无效","仅网络错误 / 结果不明"});observed.SelectedIndex=0;observed.DropDownStyle=ComboBoxStyle.DropDownList;observed.Location=new Point(0,346);observed.Width=340;content.Controls.Add(observed);
            state.Location=new Point(0,390);state.Size=new Size(830,65);content.Controls.Add(state);RefreshBrowser();}
        void RefreshBrowser(){if(renderOnly){state.Text="策略读回与浏览器执行分开记录；界面不会把写入成功当作封锁成功。";return;}var runs=Runs();if(runs.Count==0){state.Text="当前没有本入口创建的网站测试。";return;}var run=runs[0];string phase=run.RegistryRestored?"测试策略已撤销，请刷新浏览器确认恢复":run.RegistryWritten?"测试策略已发布，等待浏览器确认":"测试尚未完成，可恢复或导出诊断";state.Text="最近测试："+run.Browser+" · "+phase+"\r\n关闭入口不删除策略；恢复后同样需要刷新浏览器策略。";}
        List<BrowserRun> Runs(){return Directory.Exists(Program.UserRoot)?Directory.GetFiles(Program.UserRoot,"browser-*.json").Select(f=>Program.LoadRun(Path.GetFileNameWithoutExtension(f).Substring(8))).OrderByDescending(r=>r.CreatedUtc).ToList():new List<BrowserRun>();}
        void OpenBrowser(bool policy){string b=Convert.ToString(browser.SelectedItem),url=policy?(b=="Edge"?"edge://policy":"chrome://policy"):"https://example.com/";Process.Start(new ProcessStartInfo(Program.BrowserExe(b),url){UseShellExecute=false});}
        void RestoreBrowser(){var b=Convert.ToString(browser.SelectedItem);foreach(var run in Runs().Where(r=>r.Browser==b && (!r.RegistryRestored || !r.TaskRemoved)))Program.Restore(run.Id);RefreshBrowser();Note("已尝试只撤销本入口的策略。请在浏览器策略页重新加载，再验证测试网站恢复。");}
        void Export(){using(var picker=new FolderBrowserDialog {Description="选择诊断导出位置"})if(picker.ShowDialog(this)==DialogResult.OK){string output=Path.Combine(picker.SelectedPath,"desktop-browser-"+DateTime.UtcNow.ToString("yyyyMMddTHHmmssfffZ"));Directory.CreateDirectory(output);var results=new List<object>();foreach(var session in available){string target=Path.Combine(output,session.Id);Directory.CreateDirectory(target);foreach(string name in new[]{"workspace-status.json","workspace-fault.json","process-actions.jsonl"}){string src=Path.Combine(session.Root,"state",name);if(File.Exists(src))using(var input=new FileStream(src,FileMode.Open,FileAccess.Read,FileShare.ReadWrite|FileShare.Delete))using(var dest=File.Create(Path.Combine(target,name)))input.CopyTo(dest);}results.Add(new {runId=session.Id,serviceRunningAtEntryOpen=session.Running});}var readbacks=new List<object>();foreach(var run in Runs()){File.Copy(Program.Journal(run.Id),Path.Combine(output,"browser-"+run.Id+".json"));using(var key=Registry.CurrentUser.OpenSubKey(BrowserPolicySlot.PathFor(run.Browser)+@"\URLBlocklist")){bool present=key!=null && key.GetValueNames().Contains(run.ValueName,StringComparer.OrdinalIgnoreCase);readbacks.Add(new {runId=run.Id,browser=run.Browser,ownSlotPresent=present,ownValueMatches=present && BrowserPolicySlot.OwnValue(run.Domain,Convert.ToString(key.GetValue(run.ValueName)),key.GetValueKind(run.ValueName)==RegistryValueKind.String)});}}Program.Save(Path.Combine(output,"entry-result.json"),new {kind="AICT_DESKTOP_BROWSER_PILOT",atUtc=DateTime.UtcNow.ToString("o"),entrySha256=Program.Hash(Program.Exe),applicationSessions=results,browserPolicyReadbacks=readbacks,operatorSelectedBrowser=Convert.ToString(browser.SelectedItem),operatorObservation=Convert.ToString(observed.SelectedItem),browserAcceptanceAutomaticallyAwarded=false});var hashes=Directory.GetFiles(output,"*",SearchOption.AllDirectories).Select(f=>Program.Hash(f)+"  "+f.Substring(output.Length+1).Replace('\\','/')).ToArray();File.WriteAllLines(Path.Combine(output,"SHA256SUMS.txt"),hashes,Program.Utf8);Note("诊断已导出："+output);Process.Start(new ProcessStartInfo("explorer.exe","\""+output+"\""){UseShellExecute=true});}}
    }
}
